# Try various widths
for width in [1, 2, 3, 4]:
    rows = 28
    cols = 18
    dc = 6

    output = [[6]*cols for _ in range(rows)]
    for r in range(rows):
        output[r][dc] = 2
        if 1 <= r <= 13:
            for c in range(dc + 1, dc + width):
                output[r][c] = 9
            output[r][dc + width] = 8

    print(f"Width {width}: row 1 = {' '.join(str(v) for v in output[1][:16])}")
